// 1) Netty 长度前缀解码器：4 字节大端长度 + body，不带魔数版本号
//    maxFrameLength=8MB，lengthFieldOffset=0，lengthFieldLength=4
//    lengthAdjustment=0（长度字段值仅表示 body 长度）
//    initialBytesToStrip=4（向业务交付时已剥掉头）
ch.pipeline()
  .addLast(new LengthFieldBasedFrameDecoder(8 * 1024 * 1024, 0, 4, 0, 4))
  .addLast(new LengthFieldPrepender(4))            // 编码端自动写 4 字节长度
  .addLast(new BizHandler());

// 2) 带魔数 + 版本号的更稳健头格式：MAGIC(2) + VERSION(1) + LENGTH(4) + BODY
//    lengthFieldOffset=3，lengthFieldLength=4，lengthAdjustment=0
//    initialBytesToStrip=7（业务只拿到纯 body）
ch.pipeline()
  .addLast(new LengthFieldBasedFrameDecoder(8 * 1024 * 1024, 3, 4, 0, 7));

// 3) 不依赖框架时的手写解码 —— 突出累积缓冲与 maxFrameLength 守卫
public class LengthPrefixDecoder {
    private static final int HEADER = 4;
    private static final int MAX_FRAME = 8 * 1024 * 1024; // 必须设上限
    private final ByteBuf cumulation;                     // 跨 channelRead 累积

    public LengthPrefixDecoder(ByteBufAllocator alloc) {
        this.cumulation = alloc.buffer();
    }

    public List<ByteBuf> decode(ByteBuf in) {
        cumulation.writeBytes(in);                        // 累积，关键
        List<ByteBuf> out = new ArrayList<>();
        while (cumulation.readableBytes() >= HEADER) {
            int readerIdx = cumulation.readerIndex();
            int length = cumulation.getInt(readerIdx);    // peek，不移动指针
            if (length < 0 || length > MAX_FRAME) {
                cumulation.clear();
                throw new TooLongFrameException("frame too large: " + length);
            }
            if (cumulation.readableBytes() < HEADER + length) break; // body 没到齐，等下次
            cumulation.skipBytes(HEADER);
            out.add(cumulation.readRetainedSlice(length));
        }
        cumulation.discardReadBytes();                    // 释放已消费空间
        return out;
    }
}
